import { Component, OnInit } from '@angular/core';
import { FormBuilder, FormGroup, Validators } from '@angular/forms';
import { CamundaTask, Employee, EmployeeUpdateRequest } from '../../models/models';
import { EmployeeService } from '../../services/employee.service';
import { AuthService } from '../../services/auth.service';
import { environment } from '../../../environments/environment';

type TabType = 'overview' | 'employees' | 'tasks' | 'add';

@Component({
  selector: 'app-hr-dashboard',
  templateUrl: './hr-dashboard.component.html'
})
export class HrDashboardComponent implements OnInit {
  activeTab: TabType = 'overview';
  employees: Employee[] = [];
  pendingEmployees: Employee[] = [];
  tasks: CamundaTask[] = [];

  selectedEmployee: Employee | null = null;
  editForm!: FormGroup;
  addForm!: FormGroup;

  loading = false;
  taskLoading = false;
  msg = '';
  msgType: 'success' | 'error' = 'success';

  searchTerm = '';
  filterRole = '';
  filterStatus = '';

  camundaTasklistUrl = `${environment.camundaUrl}/app/tasklist/`;

  departments = ['Engineering','Finance','HR','Marketing','Operations','Sales','IT','Legal'];
  roles = ['HR','MANAGER','EMPLOYEE'];
  statuses = ['PENDING','ACTIVE','REJECTED','INACTIVE'];

  constructor(
    private empSvc: EmployeeService,
    public auth: AuthService,
    private fb: FormBuilder
  ) {}

  ngOnInit() {
    this.initForms();
    this.loadAll();
  }

  initForms() {
    this.editForm = this.fb.group({
      firstName:   ['', Validators.required],
      lastName:    ['', Validators.required],
      phone:       [''],
      department:  [''],
      designation: [''],
      role:        ['EMPLOYEE'],
      status:      ['ACTIVE'],
      managerId:   ['']
    });

    this.addForm = this.fb.group({
      firstName:   ['', Validators.required],
      lastName:    ['', Validators.required],
      email:       ['', [Validators.required, Validators.email]],
      password:    ['', [Validators.required, Validators.minLength(6)]],
      phone:       [''],
      department:  ['', Validators.required],
      designation: ['', Validators.required],
      role:        ['EMPLOYEE']
    });
  }

  loadAll() {
    this.loading = true;
    this.empSvc.hrGetAllEmployees().subscribe({
      next: r => { this.employees = r.data ?? []; this.loading = false; },
      error: () => { this.loading = false; this.showMsg('Failed to load employees', 'error'); }
    });
    this.empSvc.hrGetPendingEmployees().subscribe({
      next: r => this.pendingEmployees = r.data ?? []
    });
    this.loadTasks();
  }

  loadTasks() {
    this.taskLoading = true;
    this.empSvc.hrGetTasks().subscribe({
      next: r => { this.tasks = r.data ?? []; this.taskLoading = false; },
      error: () => { this.taskLoading = false; }
    });
  }

  // ── Filtering ──────────────────────────────────────────────────────────────
  get filteredEmployees(): Employee[] {
    return this.employees.filter(e => {
      const term = this.searchTerm.toLowerCase();
      const matchSearch = !term ||
        (e.firstName + ' ' + e.lastName).toLowerCase().includes(term) ||
        e.email.toLowerCase().includes(term) ||
        (e.department ?? '').toLowerCase().includes(term);
      const matchRole   = !this.filterRole   || e.role === this.filterRole;
      const matchStatus = !this.filterStatus || e.status === this.filterStatus;
      return matchSearch && matchRole && matchStatus;
    });
  }

  // ── Edit Employee ──────────────────────────────────────────────────────────
  openEdit(emp: Employee) {
    this.selectedEmployee = emp;
    this.editForm.patchValue({
      firstName: emp.firstName, lastName: emp.lastName,
      phone: emp.phone ?? '', department: emp.department ?? '',
      designation: emp.designation ?? '', role: emp.role,
      status: emp.status, managerId: emp.managerId ?? ''
    });
  }

  saveEdit() {
    if (!this.selectedEmployee || this.editForm.invalid) return;
    const req: EmployeeUpdateRequest = this.editForm.value;
    this.empSvc.hrUpdateEmployee(this.selectedEmployee.id, req).subscribe({
      next: r => {
        const idx = this.employees.findIndex(e => e.id === this.selectedEmployee!.id);
        if (idx >= 0 && r.data) this.employees[idx] = r.data;
        this.selectedEmployee = null;
        this.showMsg('Employee updated successfully!', 'success');
      },
      error: () => this.showMsg('Update failed', 'error')
    });
  }

  // ── Delete Employee ────────────────────────────────────────────────────────
  deleteEmployee(id: string) {
    if (!confirm('Deactivate this employee?')) return;
    this.empSvc.hrDeleteEmployee(id).subscribe({
      next: () => {
        this.employees = this.employees.filter(e => e.id !== id);
        this.showMsg('Employee deactivated.', 'success');
      },
      error: () => this.showMsg('Delete failed', 'error')
    });
  }

  // ── Add Employee (HR direct add) ───────────────────────────────────────────
  addEmployee() {
    if (this.addForm.invalid) return;
    import('../../services/auth.service').then(() => {
      this.auth.register(this.addForm.value).subscribe({
        next: r => {
          if (r.success) {
            this.showMsg('Employee registration started via Camunda process!', 'success');
            this.addForm.reset({ role: 'EMPLOYEE' });
            this.activeTab = 'employees';
            this.loadAll();
          } else {
            this.showMsg(r.message, 'error');
          }
        },
        error: err => this.showMsg(err.error?.message ?? 'Add failed', 'error')
      });
    });
  }

  // ── HR Approval ────────────────────────────────────────────────────────────
  approveTask(taskId: string, approved: boolean) {
    this.empSvc.hrApproveTask(taskId, approved).subscribe({
      next: r => {
        this.tasks = this.tasks.filter(t => t.taskId !== taskId);
        this.showMsg(r.message, 'success');
        this.loadAll();
      },
      error: () => this.showMsg('Action failed', 'error')
    });
  }

  // ── Stats ──────────────────────────────────────────────────────────────────
  get totalEmployees() { return this.employees.length; }
  get activeCount() { return this.employees.filter(e => e.status === 'ACTIVE').length; }
  get pendingCount() { return this.employees.filter(e => e.status === 'PENDING').length; }
  get hrCount() { return this.employees.filter(e => e.role === 'HR').length; }
  get managerCount() { return this.employees.filter(e => e.role === 'MANAGER').length; }

  showMsg(msg: string, type: 'success' | 'error') {
    this.msg = msg;
    this.msgType = type;
    setTimeout(() => this.msg = '', 4000);
  }

  setTab(tab: TabType) {
    this.activeTab = tab;
    this.selectedEmployee = null;
    this.msg = '';
  }
}
<div class="dashboard-wrapper">
  <!-- Page Header -->
  <div class="page-header">
    <div>
      <h1>🏢 HR Dashboard</h1>
      <p>Manage employees, approve registrations &amp; view Camunda tasks</p>
    </div>
    <a [href]="camundaTasklistUrl" target="_blank" class="btn-camunda">
      🔗 Open Camunda Tasklist
    </a>
  </div>

  <!-- Notification -->
  <div *ngIf="msg" class="alert" [class.alert-success]="msgType==='success'" [class.alert-error]="msgType==='error'">
    {{ msg }}
  </div>

  <!-- Tab Nav -->
  <div class="tab-nav">
    <button [class.active]="activeTab==='overview'"  (click)="setTab('overview')">📊 Overview</button>
    <button [class.active]="activeTab==='employees'" (click)="setTab('employees')">👥 Employees</button>
    <button [class.active]="activeTab==='tasks'"     (click)="setTab('tasks')">
      ✅ Approval Tasks <span class="badge" *ngIf="tasks.length">{{ tasks.length }}</span>
    </button>
    <button [class.active]="activeTab==='add'"       (click)="setTab('add')">➕ Add Employee</button>
  </div>

  <!-- ── OVERVIEW TAB ─────────────────────────────────────────────────────── -->
  <div *ngIf="activeTab==='overview'">
    <div class="stats-grid">
      <div class="stat-card stat-blue">
        <div class="stat-icon">👥</div>
        <div class="stat-value">{{ totalEmployees }}</div>
        <div class="stat-label">Total Employees</div>
      </div>
      <div class="stat-card stat-green">
        <div class="stat-icon">✅</div>
        <div class="stat-value">{{ activeCount }}</div>
        <div class="stat-label">Active</div>
      </div>
      <div class="stat-card stat-orange">
        <div class="stat-icon">⏳</div>
        <div class="stat-value">{{ pendingCount }}</div>
        <div class="stat-label">Pending Approval</div>
      </div>
      <div class="stat-card stat-purple">
        <div class="stat-icon">📋</div>
        <div class="stat-value">{{ tasks.length }}</div>
        <div class="stat-label">Camunda Tasks</div>
      </div>
    </div>

    <div class="overview-grid">
      <!-- Pending approvals quick view -->
      <div class="card">
        <div class="card-header">
          <h3>⏳ Pending Approvals</h3>
          <button class="btn-link" (click)="setTab('tasks')">View all tasks →</button>
        </div>
        <div class="empty-state" *ngIf="pendingEmployees.length===0">No pending approvals 🎉</div>
        <div class="mini-list" *ngFor="let emp of pendingEmployees.slice(0,5)">
          <span class="emp-avatar">{{ emp.firstName[0] }}{{ emp.lastName[0] }}</span>
          <span class="emp-name">{{ emp.firstName }} {{ emp.lastName }}</span>
          <span class="emp-dept">{{ emp.department }}</span>
          <span class="status-badge status-pending">PENDING</span>
        </div>
      </div>

      <!-- Role breakdown -->
      <div class="card">
        <div class="card-header"><h3>👥 Role Breakdown</h3></div>
        <div class="role-chart">
          <div class="role-row">
            <span>HR</span>
            <div class="bar-wrap"><div class="bar bar-hr" [style.width.%]="totalEmployees ? hrCount/totalEmployees*100 : 0"></div></div>
            <span class="bar-count">{{ hrCount }}</span>
          </div>
          <div class="role-row">
            <span>Manager</span>
            <div class="bar-wrap"><div class="bar bar-mgr" [style.width.%]="totalEmployees ? managerCount/totalEmployees*100 : 0"></div></div>
            <span class="bar-count">{{ managerCount }}</span>
          </div>
          <div class="role-row">
            <span>Employee</span>
            <div class="bar-wrap"><div class="bar bar-emp" [style.width.%]="totalEmployees ? (totalEmployees-hrCount-managerCount)/totalEmployees*100 : 0"></div></div>
            <span class="bar-count">{{ totalEmployees - hrCount - managerCount }}</span>
          </div>
        </div>
      </div>
    </div>
  </div>

  <!-- ── EMPLOYEES TAB ────────────────────────────────────────────────────── -->
  <div *ngIf="activeTab==='employees'">
    <!-- Filters -->
    <div class="filter-bar">
      <input type="text" [(ngModel)]="searchTerm" placeholder="🔍 Search by name, email, department..." class="search-input"/>
      <select [(ngModel)]="filterRole" class="filter-select">
        <option value="">All Roles</option>
        <option *ngFor="let r of roles" [value]="r">{{ r }}</option>
      </select>
      <select [(ngModel)]="filterStatus" class="filter-select">
        <option value="">All Statuses</option>
        <option *ngFor="let s of statuses" [value]="s">{{ s }}</option>
      </select>
      <span class="result-count">{{ filteredEmployees.length }} result(s)</span>
    </div>

    <!-- Loading -->
    <div class="loading-state" *ngIf="loading">Loading employees...</div>

    <!-- Edit Panel -->
    <div class="edit-panel" *ngIf="selectedEmployee">
      <h3>✏️ Edit: {{ selectedEmployee.firstName }} {{ selectedEmployee.lastName }}</h3>
      <form [formGroup]="editForm" (ngSubmit)="saveEdit()">
        <div class="form-row">
          <div class="form-group">
            <label>First Name</label>
            <input formControlName="firstName" class="form-control"/>
          </div>
          <div class="form-group">
            <label>Last Name</label>
            <input formControlName="lastName" class="form-control"/>
          </div>
        </div>
        <div class="form-row">
          <div class="form-group">
            <label>Phone</label>
            <input formControlName="phone" class="form-control"/>
          </div>
          <div class="form-group">
            <label>Department</label>
            <select formControlName="department" class="form-control">
              <option *ngFor="let d of departments" [value]="d">{{ d }}</option>
            </select>
          </div>
        </div>
        <div class="form-row">
          <div class="form-group">
            <label>Designation</label>
            <input formControlName="designation" class="form-control"/>
          </div>
          <div class="form-group">
            <label>Role</label>
            <select formControlName="role" class="form-control">
              <option *ngFor="let r of roles" [value]="r">{{ r }}</option>
            </select>
          </div>
        </div>
        <div class="form-row">
          <div class="form-group">
            <label>Status</label>
            <select formControlName="status" class="form-control">
              <option *ngFor="let s of statuses" [value]="s">{{ s }}</option>
            </select>
          </div>
        </div>
        <div class="btn-group">
          <button type="submit" class="btn-primary" [disabled]="editForm.invalid">Save Changes</button>
          <button type="button" class="btn-secondary" (click)="selectedEmployee=null">Cancel</button>
        </div>
      </form>
    </div>

    <!-- Employee Table -->
    <div class="table-wrap">
      <table class="data-table">
        <thead>
          <tr>
            <th>Employee</th><th>Email</th><th>Department</th>
            <th>Designation</th><th>Role</th><th>Status</th><th>Actions</th>
          </tr>
        </thead>
        <tbody>
          <tr *ngFor="let emp of filteredEmployees">
            <td>
              <div class="emp-cell">
                <span class="emp-avatar sm">{{ emp.firstName[0] }}{{ emp.lastName[0] }}</span>
                {{ emp.firstName }} {{ emp.lastName }}
              </div>
            </td>
            <td>{{ emp.email }}</td>
            <td>{{ emp.department ?? '—' }}</td>
            <td>{{ emp.designation ?? '—' }}</td>
            <td><span class="role-badge role-{{emp.role.toLowerCase()}}">{{ emp.role }}</span></td>
            <td><span class="status-badge status-{{emp.status.toLowerCase()}}">{{ emp.status }}</span></td>
            <td>
              <div class="action-btns">
                <button class="btn-icon btn-edit" (click)="openEdit(emp)" title="Edit">✏️</button>
                <button class="btn-icon btn-del" (click)="deleteEmployee(emp.id)" title="Deactivate">🗑️</button>
              </div>
            </td>
          </tr>
          <tr *ngIf="filteredEmployees.length===0">
            <td colspan="7" class="empty-row">No employees found</td>
          </tr>
        </tbody>
      </table>
    </div>
  </div>

  <!-- ── TASKS TAB ─────────────────────────────────────────────────────────── -->
  <div *ngIf="activeTab==='tasks'">
    <div class="task-header">
      <h3>Camunda HR Approval Tasks</h3>
      <div>
        <button class="btn-secondary" (click)="loadTasks()">🔄 Refresh</button>
        <a [href]="camundaTasklistUrl" target="_blank" class="btn-camunda ml">Open in Tasklist</a>
      </div>
    </div>

    <div class="loading-state" *ngIf="taskLoading">Loading tasks from Camunda engine...</div>

    <div class="empty-state" *ngIf="!taskLoading && tasks.length===0">
      ✅ No pending HR approval tasks
    </div>

    <div class="task-grid" *ngIf="!taskLoading">
      <div class="task-card" *ngFor="let task of tasks">
        <div class="task-card-header">
          <span class="task-name">{{ task.taskName }}</span>
          <span class="task-date">{{ task.created | date:'short' }}</span>
        </div>
        <div class="task-detail">
          <span class="label">Process ID:</span>
          <code>{{ task.processInstanceId }}</code>
        </div>
        <div class="task-detail">
          <span class="label">Task ID:</span>
          <code>{{ task.taskId }}</code>
        </div>
        <div class="task-actions">
          <button class="btn-approve" (click)="approveTask(task.taskId, true)">✅ Approve</button>
          <button class="btn-reject"  (click)="approveTask(task.taskId, false)">❌ Reject</button>
        </div>
      </div>
    </div>
  </div>

  <!-- ── ADD EMPLOYEE TAB ──────────────────────────────────────────────────── -->
  <div *ngIf="activeTab==='add'">
    <div class="card form-card">
      <h3>➕ Add New Employee (starts Camunda process)</h3>
      <form [formGroup]="addForm" (ngSubmit)="addEmployee()">
        <div class="form-row">
          <div class="form-group">
            <label>First Name *</label>
            <input formControlName="firstName" class="form-control" placeholder="John"/>
          </div>
          <div class="form-group">
            <label>Last Name *</label>
            <input formControlName="lastName" class="form-control" placeholder="Doe"/>
          </div>
        </div>
        <div class="form-row">
          <div class="form-group">
            <label>Email *</label>
            <input type="email" formControlName="email" class="form-control" placeholder="john@company.com"/>
          </div>
          <div class="form-group">
            <label>Phone</label>
            <input formControlName="phone" class="form-control" placeholder="+1-555-0100"/>
          </div>
        </div>
        <div class="form-row">
          <div class="form-group">
            <label>Department *</label>
            <select formControlName="department" class="form-control">
              <option value="">Select...</option>
              <option *ngFor="let d of departments" [value]="d">{{ d }}</option>
            </select>
          </div>
          <div class="form-group">
            <label>Designation *</label>
            <input formControlName="designation" class="form-control" placeholder="Software Engineer"/>
          </div>
        </div>
        <div class="form-row">
          <div class="form-group">
            <label>Role</label>
            <select formControlName="role" class="form-control">
              <option value="EMPLOYEE">Employee</option>
              <option value="MANAGER">Manager</option>
              <option value="HR">HR</option>
            </select>
          </div>
          <div class="form-group">
            <label>Password *</label>
            <input type="password" formControlName="password" class="form-control" placeholder="Min 6 characters"/>
          </div>
        </div>
        <button type="submit" class="btn-primary" [disabled]="addForm.invalid">
          🚀 Start Registration Process
        </button>
      </form>
    </div>
  </div>
</div>
